--
-- Table structure for table `core_crime`
--

DROP TABLE IF EXISTS `core_crime`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `core_crime` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `crime_id` varchar(50) NOT NULL,
  `date` date NOT NULL,
  `time` varchar(10) NOT NULL,
  `description` longtext NOT NULL,
  `priority` varchar(20) NOT NULL,
  `status` varchar(30) NOT NULL,
  `sections` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`sections`)),
  `notes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`notes`)),
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `officer_id` bigint(20) NOT NULL,
  `crime_category_id` bigint(20) NOT NULL,
  `location_id` bigint(20) NOT NULL,
  `citizen_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `crime_id` (`crime_id`),
  KEY `core_crime_location_id_c169fc01_fk_core_location_id` (`location_id`),
  KEY `core_crime_officer_id_2d468981_fk_authentication_officer_id` (`officer_id`),
  KEY `core_crime_crime_category_id_648b3f92_fk_core_crimecategory_id` (`crime_category_id`),
  KEY `core_crime_citizen_id_b3794088_fk_authentication_citizen_id` (`citizen_id`),
  CONSTRAINT `core_crime_citizen_id_b3794088_fk_authentication_citizen_id` FOREIGN KEY (`citizen_id`) REFERENCES `authentication_citizen` (`id`),
  CONSTRAINT `core_crime_crime_category_id_648b3f92_fk_core_crimecategory_id` FOREIGN KEY (`crime_category_id`) REFERENCES `core_crimecategory` (`id`),
  CONSTRAINT `core_crime_location_id_c169fc01_fk_core_location_id` FOREIGN KEY (`location_id`) REFERENCES `core_location` (`id`),
  CONSTRAINT `core_crime_officer_id_2d468981_fk_authentication_officer_id` FOREIGN KEY (`officer_id`) REFERENCES `authentication_officer` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5081 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

